select info from (select 1 as ord, 'ADMIN_USERS total=' || count(*)::text || ' ativos=' || count(*) filter (where is_active)::text || ' com_auth_user_id=' || count(auth_user_id)::text as info from public.admin_users union all select 2, 'IS_SUPER_ADMIN def | ' || replace(pg_get_functiondef(p.oid), chr(10), ' ') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='is_super_admin') s order by ord;